package com.keepcalm.placementportal.models.round;import com.keepcalm.placementportal.enums.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.Instant;import java.util.List;
public final class RoundDtos{private RoundDtos(){}public record RoundDto(Long id,Long driveId,String name,String roundType,int roundOrder,Instant startsAt,Instant endsAt,String location,boolean resultsPublished,long version){}public record Upsert(@NotBlank String name,@NotBlank String roundType,@Min(1)int roundOrder,@NotNull Instant startsAt,@NotNull Instant endsAt,String location){}public record ParticipantDto(Long id,Long applicationId,Long studentId,String rollNumber,String studentName,AttendanceStatus attendanceStatus,RoundResultStatus resultStatus,BigDecimal score){}public record ResultItem(@NotNull Long participantId,@NotNull RoundResultStatus status,BigDecimal score,@Size(max=1000)String notes,AttendanceStatus attendanceStatus){}public record Results(@NotEmpty List<@Valid ResultItem> results){} }
